            if (!found.elements.length) continue;
            let optionCount = queryAllSafely(entry.document, 'li.form-cell').length;
            let candidate = {
                document: entry.document,
                path: entry.path,
                depth: entry.depth,
                selector: found.selector,
                elements: found.elements,
                optionCount: optionCount,
                blockedFrames: scan.blockedFrames,
                scannedDocuments: scan.documents.length
            };
